INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_VITAL_ETZ_CHAIM','primary text','Hayyim Vital, Etz Chaim (the Tree of Life — Luria''s teachings, c. 1573)','Jewish Mystical'),
 ('SRC_SHIVHEI_BESHT','primary text','Shivhei ha-Besht (In Praise of the Baal Shem Tov, 1814)','Jewish Mystical')
INSERT INTO _e VALUES
 ('ENT_JM_SAFED_KABBALISTS','Safed Kabbalists','Collective','Kabbalist','Jewish Mystical','[''kabbalah'', ''mysticism'', ''Torah study'']','A','The 16th-century circle of mystics gathered at Safed in the Galilee, the center of post-expulsion Kabbalah; home to Cordovero, Luria, Vital, Karo and Alkabetz.'),
 ('ENT_JM_HASIDISM','Hasidism','Collective','Hasidic master','Jewish Mystical','[''mysticism'', ''devekut'', ''popular piety'']','A','The Hasidic movement of devotional mysticism arising in 18th-century Eastern Europe, founded by the Baal Shem Tov and spread through successive rebbes.'),
 ('ENT_JM_SABBATEANS','Sabbateans','Collective','Messianic claimant','Jewish Mystical','[''messianism'', ''mysticism'']','A','The 17th-century messianic movement that proclaimed Sabbatai Zevi as the messiah, drawing on Lurianic eschatology and erupting in 1665-66.'),
 ('ENT_JM_CORDOVERO','Moses Cordovero (Ramak)','Mystic','Safed mystic','Jewish Mystical','[''kabbalah'', ''systematic theology'']','A','Moses ben Jacob Cordovero (1522-1570), the great systematizer of pre-Lurianic Kabbalah in Safed; author of Pardes Rimmonim. His school preceded and shaped Luria''s.'),
 ('ENT_JM_LURIA','Isaac Luria (the Ari)','Mystic','Lurianic kabbalist','Jewish Mystical','[''kabbalah'', ''mysticism'', ''cosmology'']','A','Isaac ben Solomon Luria (1534-1572), ''the Ari,'' the central figure of Safed Kabbalah, whose teaching of Tzimtzum, Shevirat ha-Kelim and Tikkun reshaped all later Jewish mysticism. He wrote almost nothing; his doctrine survives through Vital.'),
 ('ENT_JM_VITAL','Hayyim Vital','Mystic','Lurianic kabbalist','Jewish Mystical','[''kabbalah'', ''mysticism'']','A','Hayyim ben Joseph Vital (1542-1620), Luria''s foremost disciple and recorder; his Etz Chaim is the chief written source for the Lurianic system.'),
 ('ENT_JM_KARO','Joseph Karo','Mystic','Safed mystic','Jewish Mystical','[''halakhah'', ''kabbalah'', ''mysticism'']','A','Joseph Karo (1488-1575), Safed jurist-mystic, author of the Shulchan Aruch code of law and the mystical diary Maggid Mesharim recording his angelic mentor (the maggid).'),
 ('ENT_JM_ALKABETZ','Solomon Alkabetz','Mystic','Safed mystic','Jewish Mystical','[''kabbalah'', ''liturgy'', ''mysticism'']','A','Solomon ben Moses Alkabetz (c.1500-1576), Safed kabbalist and poet, author of the hymn Lekhah Dodi welcoming the Sabbath bride (the Shekhinah); Cordovero''s teacher and brother-in-law.'),
 ('ENT_JM_LUZZATTO','Moses Hayyim Luzzatto (Ramchal)','Mystic','Lurianic kabbalist','Jewish Mystical','[''kabbalah'', ''ethics'', ''mysticism'']','A','Moses Hayyim Luzzatto (1707-1746), ''the Ramchal,'' Italian kabbalist and ethicist who systematized Lurianic doctrine; author of Mesillat Yesharim and recipient of a maggid. Suspected of Sabbatean leanings and forced to suppress his kabbalistic writings.'),
 ('ENT_JM_SABBATAI_ZEVI','Sabbatai Zevi','Mystic','Messianic claimant','Jewish Mystical','[''messianism'', ''mysticism'']','A','Sabbatai Zevi (1626-1676), the self-proclaimed Jewish messiah whose movement convulsed Jewry in 1665-66; he converted to Islam under Ottoman threat, splitting his followers. Drew on Lurianic redemption theology.'),
 ('ENT_JM_NATHAN_GAZA','Nathan of Gaza','Mystic','Messianic claimant','Jewish Mystical','[''messianism'', ''prophecy'', ''kabbalah'']','A','Abraham Nathan ben Elisha Hayyim Ashkenazi (1643-1680), ''Nathan of Gaza,'' the prophet and theologian of the Sabbatean movement who proclaimed Sabbatai Zevi as messiah and built its Lurianic-based theology, including after the apostasy.'),
 ('ENT_JM_BESHT','Baal Shem Tov (Israel ben Eliezer)','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''devekut'', ''healing'']','A','Israel ben Eliezer (c.1698-1760), the ''Baal Shem Tov'' (Master of the Good Name), founder of Hasidism; emphasized joyful devotion (devekut) and the divine presence in all things. Known through the hagiographic Shivhei ha-Besht.'),
 ('ENT_JM_DOV_BER','Dov Ber of Mezeritch (the Maggid)','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''devekut'']','A','Dov Ber of Mezeritch (c.1704-1772), ''the Great Maggid,'' chief disciple and successor of the Baal Shem Tov who organized Hasidism into a movement and trained the generation of rebbes who spread it.'),
 ('ENT_JM_SCHNEUR_ZALMAN','Schneur Zalman of Liadi','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''intellectual Hasidism'']','A','Schneur Zalman of Liadi (1745-1812), disciple of Dov Ber and founder of Chabad (Lubavitch) Hasidism; author of the Tanya, which fused Lurianic Kabbalah with an intellectual contemplative path.'),
 ('ENT_JM_NACHMAN','Nachman of Breslov','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''storytelling'', ''devotion'']','A','Nachman of Breslov (1772-1810), great-grandson of the Baal Shem Tov and founder of Breslov Hasidism; taught hitbodedut (secluded prayer) and composed mystical tales.'),
 ('ENT_JM_LEVI_YITZHAK','Levi Yitzhak of Berditchev','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''devotion'', ''intercession'']','A','Levi Yitzhak of Berditchev (1740-1809), disciple of Dov Ber and beloved Hasidic rebbe famed as the compassionate ''defender'' of Israel before God; author of Kedushat Levi.'),
 ('ENT_JM_ELIMELECH','Elimelech of Lizhensk','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''tzaddikism'']','A','Elimelech of Lizhensk (1717-1787), disciple of Dov Ber whose Noam Elimelech articulated the doctrine of the tzaddik as channel of divine blessing, shaping Polish-Galician Hasidism.'),
 ('ENT_JM_JACOB_JOSEPH','Jacob Joseph of Polonne','Mystic','Hasidic master','Jewish Mystical','[''mysticism'', ''homiletics'']','A','Jacob Joseph of Polonne (d. c.1782), disciple of the Baal Shem Tov and the first to record his teachings in print (Toldot Yaakov Yosef), the earliest Hasidic book.'),
 ('ENT_JM_VILNA_GAON','Elijah of Vilna (the Vilna Gaon)','Mystic','Kabbalist','Jewish Mystical','[''Torah study'', ''kabbalah'', ''halakhah'']','A','Elijah ben Solomon Zalman (1720-1797), ''the Vilna Gaon,'' the supreme Lithuanian Talmudist and kabbalist; leader of the Mitnagdim who fiercely opposed the rise of Hasidism, issuing bans against it.'),
 ('ENT_JM_CHAYYIM_VOLOZHIN','Chayyim of Volozhin','Mystic','Kabbalist','Jewish Mystical','[''Torah study'', ''kabbalah'']','A','Chayyim of Volozhin (1749-1821), foremost disciple of the Vilna Gaon and founder of the Volozhin yeshiva; his Nefesh ha-Chayyim gave the Mitnagdic movement its kabbalistic-intellectual theology.');
