INSERT INTO _r VALUES
 ('ENT_JM_CORDOVERO','member_of','ENT_JM_SAFED_KABBALISTS','high','Cordovero led the systematizing school of Kabbalah in 16th-c Safed.'),
 ('ENT_JM_LURIA','member_of','ENT_JM_SAFED_KABBALISTS','high','Luria, the Ari, was the central master of the Safed circle.'),
 ('ENT_JM_VITAL','member_of','ENT_JM_SAFED_KABBALISTS','high','Vital was a leading member of Luria''s Safed circle.'),
 ('ENT_JM_KARO','member_of','ENT_JM_SAFED_KABBALISTS','high','Karo was a pillar of the Safed mystical-halakhic community.'),
 ('ENT_JM_ALKABETZ','member_of','ENT_JM_SAFED_KABBALISTS','high','Alkabetz, author of Lekhah Dodi, belonged to the Safed circle.'),
 ('ENT_JM_LURIA','taught_by','ENT_JM_CORDOVERO','medium','Luria briefly studied with Cordovero in Safed; his system built upon and superseded Cordovero''s.'),
 ('ENT_JM_VITAL','taught_by','ENT_JM_LURIA','high','Vital was Luria''s foremost disciple and the recorder of his teachings.'),
 ('ENT_JM_VITAL','taught_by','ENT_JM_CORDOVERO','high','Vital first studied Cordoverian Kabbalah before becoming Luria''s disciple.'),
 ('ENT_JM_CORDOVERO','taught_by','ENT_JM_ALKABETZ','high','Alkabetz was Cordovero''s teacher and brother-in-law.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_TZIMTZUM','high','Luria taught the doctrine of Tzimtzum, the divine self-contraction.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_RESHIMU','high','The Reshimu (residue) is a core element of Luria''s cosmogony.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_KAV','high','The Kav (ray of light entering the void) is part of Luria''s emanation scheme.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_SHEVIRAH','high','Luria taught Shevirat ha-Kelim, the breaking of the vessels.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_TIKKUN','high','Luria taught Tikkun, the cosmic restoration.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_TOHU','high','Olam ha-Tohu, the World of Chaos that shattered, is central to Lurianic cosmology.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_NETZOTZOT','high','The scattered netzotzot (holy sparks) to be raised are a Lurianic doctrine.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_ADAM_KADMON','high','Adam Kadmon, the primordial man, is a foundational Lurianic figure.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_ARIKH_ANPIN','high','Luria''s partzuf doctrine includes Arikh Anpin (the Long Face).'),
 ('ENT_JM_LURIA','reveals','ENT_JM_ATIKA_KADISHA','high','Atika Kadisha (the Holy Ancient One) is a Lurianic partzuf.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_ABBA','high','The partzuf Abba (Father) belongs to Luria''s configuration of the sefirot.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_IMMA','high','The partzuf Imma (Mother) belongs to Luria''s configuration.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_ZEIR_ANPIN','high','Zeir Anpin (the Small Face) is a central Lurianic partzuf.'),
 ('ENT_JM_LURIA','reveals','ENT_JM_NUKVA','high','Nukva (the Female) is a Lurianic partzuf paired with Zeir Anpin.'),
 ('ENT_JM_VITAL','reveals','ENT_JM_TIKKUN','high','Vital transmitted Luria''s Tikkun doctrine in Etz Chaim.'),
 ('ENT_JM_VITAL','reveals','ENT_JM_SHEVIRAH','high','Vital recorded the Shevirat ha-Kelim teaching in Etz Chaim.'),
 ('ENT_JM_LUZZATTO','reception_of','ENT_JM_TIKKUN','high','Luzzatto systematized the Lurianic doctrine of Tikkun for later readers.'),
 ('ENT_JM_LUZZATTO','reception_of','ENT_JM_EIN_SOF','medium','Luzzatto''s metaphysics centers on the unfolding of the Ein Sof''s providence.'),
 ('ENT_JM_ALKABETZ','aligned_with','ENT_JM_SHEKHINAH','high','Alkabetz''s Lekhah Dodi welcomes the Sabbath as the Shekhinah, the divine bride.'),
 ('ENT_JM_SABBATAI_ZEVI','member_of','ENT_JM_SABBATEANS','high','Sabbatai Zevi was the messianic figurehead of the Sabbatean movement.'),
 ('ENT_JM_NATHAN_GAZA','member_of','ENT_JM_SABBATEANS','high','Nathan of Gaza was the prophet-theologian of the Sabbatean movement.'),
 ('ENT_JM_NATHAN_GAZA','aligned_with','ENT_JM_SABBATAI_ZEVI','high','Nathan of Gaza proclaimed Sabbatai Zevi as the messiah and built the theology around him.'),
 ('ENT_JM_SABBATEANS','reception_of','ENT_JM_TIKKUN','high','Sabbatean messianism interpreted Tikkun and Lurianic redemption as fulfilled in Sabbatai Zevi.'),
 ('ENT_JM_NATHAN_GAZA','reception_of','ENT_JM_QLIPHOTH','medium','Nathan''s theology of the apostasy framed the messiah''s descent among the qliphoth to raise the sparks.'),
 ('ENT_JM_BESHT','member_of','ENT_JM_HASIDISM','high','The Baal Shem Tov is the founder of the Hasidic movement.'),
 ('ENT_JM_DOV_BER','member_of','ENT_JM_HASIDISM','high','Dov Ber, the Maggid, succeeded the Baal Shem Tov as leader of Hasidism.'),
 ('ENT_JM_SCHNEUR_ZALMAN','member_of','ENT_JM_HASIDISM','high','Schneur Zalman founded the Chabad branch of Hasidism.'),
 ('ENT_JM_NACHMAN','member_of','ENT_JM_HASIDISM','high','Nachman founded the Breslov branch of Hasidism.'),
 ('ENT_JM_LEVI_YITZHAK','member_of','ENT_JM_HASIDISM','high','Levi Yitzhak of Berditchev was a leading Hasidic rebbe.'),
 ('ENT_JM_ELIMELECH','member_of','ENT_JM_HASIDISM','high','Elimelech of Lizhensk shaped Polish-Galician Hasidism.'),
 ('ENT_JM_JACOB_JOSEPH','member_of','ENT_JM_HASIDISM','high','Jacob Joseph of Polonne was the first to record the Baal Shem Tov''s teachings in print.'),
 ('ENT_JM_DOV_BER','taught_by','ENT_JM_BESHT','high','Dov Ber was the chief disciple of the Baal Shem Tov.'),
 ('ENT_JM_JACOB_JOSEPH','taught_by','ENT_JM_BESHT','high','Jacob Joseph was a direct disciple of the Baal Shem Tov.'),
 ('ENT_JM_SCHNEUR_ZALMAN','taught_by','ENT_JM_DOV_BER','high','Schneur Zalman was a disciple of Dov Ber, the Maggid.'),
 ('ENT_JM_LEVI_YITZHAK','taught_by','ENT_JM_DOV_BER','high','Levi Yitzhak of Berditchev was a disciple of Dov Ber.'),
 ('ENT_JM_ELIMELECH','taught_by','ENT_JM_DOV_BER','high','Elimelech of Lizhensk was a disciple of Dov Ber.'),
 ('ENT_JM_NACHMAN','child_of','ENT_JM_BESHT','medium','Nachman of Breslov was the great-grandson of the Baal Shem Tov (descent line, not literal parent).'),
 ('ENT_JM_SCHNEUR_ZALMAN','reception_of','ENT_JM_TZIMTZUM','high','The Tanya develops a distinctive contemplative reading of the Lurianic Tzimtzum.'),
 ('ENT_JM_SCHNEUR_ZALMAN','reception_of','ENT_JM_EIN_SOF','high','Chabad theology centers on the immanence of the Ein Sof within creation.'),
 ('ENT_JM_BESHT','reception_of','ENT_JM_NETZOTZOT','high','The Baal Shem Tov popularized the Lurianic raising of holy sparks (netzotzot) in everyday life.'),
 ('ENT_JM_VILNA_GAON','opposes','ENT_JM_HASIDISM','high','The Vilna Gaon led the Mitnagdim and issued bans against the Hasidic movement.'),
 ('ENT_JM_CHAYYIM_VOLOZHIN','taught_by','ENT_JM_VILNA_GAON','high','Chayyim of Volozhin was the foremost disciple of the Vilna Gaon.'),
 ('ENT_JM_CHAYYIM_VOLOZHIN','opposes','ENT_JM_HASIDISM','medium','Chayyim of Volozhin gave the Mitnagdic opposition to Hasidism its theological framework in Nefesh ha-Chayyim.'),
 ('ENT_JM_VILNA_GAON','reception_of','ENT_JM_SEFIROT','medium','The Vilna Gaon was a serious kabbalist who commented on the sefirotic system within the Lithuanian tradition.');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
